<script setup lang="ts">
import { computed, ref } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { account, enterSample } from '@/lib/account'
import { configured, supabase } from '@/lib/supabase'
const route = useRoute(), router = useRouter(), email = ref(''), password = ref(''), busy = ref(false), error = ref(''), message = ref('')
const mode = computed(() => String(route.params.mode || 'signin'))
const title = computed(() => ({ signin: 'Welcome back.', signup: 'A workspace of your own.', recover: 'Find your way back.', password: 'Choose a new password.', callback: 'Open your workspace.' })[mode.value] || 'Welcome back.')
async function submit() {
  if (!supabase) return
  busy.value = true; error.value = ''; message.value = ''
  const redirectTo = new URL('/auth/callback', window.location.origin).href
  try {
    if (mode.value === 'signup') { const { error } = await supabase.auth.signUp({ email: email.value, password: password.value, options: { emailRedirectTo: redirectTo } }); if (error) throw error; message.value = 'Check your email for a verification link. If this address already has an account, use sign in or password recovery.' }
    else if (mode.value === 'recover') { const { error } = await supabase.auth.resetPasswordForEmail(email.value, { redirectTo: new URL('/auth/password', window.location.origin).href }); if (error) throw error; message.value = 'If this email has an account, a recovery link is on its way.' }
    else if (mode.value === 'password') { if (!account.recovery) throw new Error('Open the link from your recovery email before setting a new password.'); const { error } = await supabase.auth.updateUser({ password: password.value }); if (error) throw error; account.recovery = false; await router.replace('/today') }
    else { const { error } = await supabase.auth.signInWithPassword({ email: email.value, password: password.value }); if (error) throw error }
  } catch (e) { error.value = mode.value === 'signin' ? 'Sign-in failed. Check your email and password, or use password recovery.' : (e as Error).message }
  finally { busy.value = false }
}
function change(next: string) { error.value = ''; message.value = ''; password.value = ''; void router.push('/auth/' + next) }
</script>
<template><div class="auth-shell"><aside class="auth-story"><div class="wordmark"><span class="mark" aria-hidden="true">L</span>Lancealot</div><div><h1>Good work deserves a clear head.</h1><p>Your projects, follow-ups and unpaid invoices. Together in one private workspace.</p></div><div class="auth-footer">A quieter way to keep client work moving.</div></aside><main class="auth-form"><template v-if="!configured"><h1>Your workspace starts here.</h1><p class="secondary">Account setup is pending. You can explore a sample workspace while your private connection is being prepared.</p><button class="primary" @click="enterSample">Explore sample workspace</button><p class="secondary" style="margin-top:20px">Fictional records only. Sample changes aren't saved.</p></template><template v-else><h1>{{ title }}</h1><p class="secondary">{{ mode === 'signup' ? 'Create a private account. Verify your email to get started.' : mode === 'recover' ? 'We’ll email a link to reset your password.' : mode === 'password' ? 'Use a strong password you haven’t used elsewhere.' : 'Sign in to your private client records and follow-ups.' }}</p><p v-if="account.problem" class="notice error" role="alert">{{ account.problem }}</p><form @submit.prevent="submit"><div v-if="mode !== 'password'" class="field"><label for="email">Email</label><input id="email" v-model="email" type="email" autocomplete="email" required /></div><div v-if="mode !== 'recover'" class="field"><label for="password">{{ mode === 'password' ? 'New password' : 'Password' }}</label><input id="password" v-model="password" type="password" :autocomplete="mode === 'signin' ? 'current-password' : 'new-password'" :minlength="mode === 'signin' ? undefined : 12" required /><small v-if="mode !== 'signin'">At least 12 characters.</small></div><p v-if="error" class="error-text" role="alert">{{ error }}</p><p v-if="message" class="notice success" role="status">{{ message }}</p><button class="primary" :disabled="busy" type="submit">{{ busy ? 'Please wait…' : mode === 'signup' ? 'Create account' : mode === 'recover' ? 'Send recovery link' : mode === 'password' ? 'Save new password' : 'Sign in' }}</button></form><div class="actions"><button v-if="mode !== 'signin'" class="quiet" @click="change('signin')">Sign in</button><button v-if="mode === 'signin'" class="quiet" @click="change('signup')">Create account</button><button v-if="mode !== 'recover' && mode !== 'password'" class="quiet" @click="change('recover')">Forgot password?</button></div><hr class="divider" /><button class="quiet" @click="enterSample">Explore sample workspace</button></template></main></div></template>
